                if (_.cmd == HdbootSerial.RomCmd.run) != (i == len(self.rom_frames) - 1):
                    raise kaitaistruct.ConsistencyError(u"rom_frames", i == len(self.rom_frames) - 1, _.cmd == HdbootSerial.RomCmd.run)

