                if self.loader_frames[i]._root != self._root:
                    raise kaitaistruct.ConsistencyError(u"loader_frames", self._root, self.loader_frames[i]._root)
                if self.loader_frames[i]._parent != self:
                    raise kaitaistruct.ConsistencyError(u"loader_frames", self, self.loader_frames[i]._parent)

