    class MiniWriteBody(ReadWriteKaitaiStruct):
        """WRITE one 32-bit word."""
        def __init__(self, _io=None, _parent=None, _root=None):
            super(HdbootSerial.MiniWriteBody, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.addr = self._io.read_u4be()
            self._raw_value = self._io.read_bytes(4)
            _io__raw_value = KaitaiStream(BytesIO(self._raw_value))
            self.value = HdbootSerial.WordEitherEndian(_io__raw_value, self, self._root)
            self.value._read()
            self._dirty = False


        def _fetch_instances(self):
            pass
            self.value._fetch_instances()


        def _write__seq(self, io=None):
            super(HdbootSerial.MiniWriteBody, self)._write__seq(io)
            self._io.write_u4be(self.addr)
            _io__raw_value = KaitaiStream(BytesIO(bytearray(4)))
            self._io.add_child_stream(_io__raw_value)
            _pos2 = self._io.pos()
            self._io.seek(self._io.pos() + (4))
            def handler(parent, _io__raw_value=_io__raw_value):
                self._raw_value = _io__raw_value.to_byte_array()
                if len(self._raw_value) != 4:
                    raise kaitaistruct.ConsistencyError(u"raw(value)", 4, len(self._raw_value))
                parent.write_bytes(self._raw_value)
            _io__raw_value.write_back_handler = KaitaiStream.WriteBackHandler(_pos2, handler)
            self.value._write__seq(_io__raw_value)


        def _check(self):
            if self.value._root != self._root:
                raise kaitaistruct.ConsistencyError(u"value", self._root, self.value._root)
            if self.value._parent != self:
                raise kaitaistruct.ConsistencyError(u"value", self, self.value._parent)
            self._dirty = False


