    class RomBootAnnounce(ReadWriteKaitaiStruct):
        """What a DM-32 sends on UART0 at power-on when no host answers: NOTIFY, then (after the
        handshake window, once DH_FLAG matched) the four bytes of the entry address it is about to
        jump to, least significant byte first. Observed with a non-stock image's entry word; for
        stock firmware (entry 0x03001000) that makes 02 24 00 03 00 10 00 03.
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(HdbootSerial.RomBootAnnounce, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.notify = HdbootSerial.MiniDeviceFrame(self._io, self, self._root)
            self.notify._read()
            self.entry = self._io.read_u4le()
            self._dirty = False


        def _fetch_instances(self):
            pass
            self.notify._fetch_instances()


        def _write__seq(self, io=None):
            super(HdbootSerial.RomBootAnnounce, self)._write__seq(io)
            self.notify._write__seq(self._io)
            self._io.write_u4le(self.entry)


        def _check(self):
            if self.notify._root != self._root:
                raise kaitaistruct.ConsistencyError(u"notify", self._root, self.notify._root)
            if self.notify._parent != self:
                raise kaitaistruct.ConsistencyError(u"notify", self, self.notify._parent)
            self._dirty = False


    class WordEitherEndian(ReadWriteKaitaiStruct):
        """A 4-byte word whose byte order is not known; both readings are offered."""
        def __init__(self, _io=None, _parent=None, _root=None):
            super(HdbootSerial.WordEitherEndian, self).__init__(_io)
            self._parent = _parent
            self._root = _root
            self._should_write_as_le = False
            self.as_le__enabled = True

        def _read(self):
            self.as_be = self._io.read_u4be()
            self._dirty = False


        def _fetch_instances(self):
            pass
            _ = self.as_le
            if hasattr(self, '_m_as_le'):
                pass



        def _write__seq(self, io=None):
            super(HdbootSerial.WordEitherEndian, self)._write__seq(io)
            self._should_write_as_le = self.as_le__enabled
            self._io.write_u4be(self.as_be)


        def _check(self):
            if self.as_le__enabled:
                pass

            self._dirty = False

        @property
        def as_le(self):
            """The same 4 bytes read little-endian."""
            if self._should_write_as_le:
                self._write_as_le()
            if hasattr(self, '_m_as_le'):
                return self._m_as_le

            if not self.as_le__enabled:
                return None

            _pos = self._io.pos()
            self._io.seek(0)
            self._m_as_le = self._io.read_u4le()
            self._io.seek(_pos)
            return getattr(self, '_m_as_le', None)

        @as_le.setter
        def as_le(self, v):
            self._dirty = True
            self._m_as_le = v

        def _write_as_le(self):
            self._should_write_as_le = False
            _pos = self._io.pos()
            self._io.seek(0)
            self._io.write_u4le(self._m_as_le)
            self._io.seek(_pos)



